932 :           token = next();
933 :           continue retry;
934 : 
935 :         default:
936 :           if (token == JsDocToken.STAR && state == State.SEARCHING_ANNOTATION) {
937 :             token = next();
938 :             continue retry;
939 :           } else {
940 :             state = State.SEARCHING_NEWLINE;
941 :             token = eatTokensUntilEOL();
942 :             continue retry;
943 :           }
944 :       }
945 : 
946 :       // next token
947 :       token = next();
948 :     }
949 :   }"

